import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from './context/AuthContext';
import { useDataSync } from './context/DataSyncContext';
import Welcome from './components/Welcome';
import Navbar from './components/Navbar';
import NotificationsDrawer from './components/NotificationsDrawer';
import Dashboard from './components/Dashboard';
import BillsRent from './components/BillsRent';
import Expenses from './components/Expenses';
import Pantry from './components/Pantry';
import Budget from './components/Budget';
import AIFeatures from './components/AIFeatures';
import ExpenseSummary from './components/ExpenseSummary';

export default function App() {
  const { isAuthenticated, loading, authFetch } = useAuth();
  const { subscribeToChanges } = useDataSync();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [notifications, setNotifications] = useState([]);

  const fetchNotifications = useCallback(async () => {
    if (!isAuthenticated) return;
    try {
      const res = await authFetch('/api/notifications');
      if (res.ok) {
        const data = await res.json();
        setNotifications(data.notifications || []);
      }
    } catch (err) {
      console.error('Failed to load notifications:', err);
    }
  }, [isAuthenticated, authFetch]);

  useEffect(() => {
    if (isAuthenticated) {
      fetchNotifications();
      // Poll every 60s for time-based updates (bill due dates changing)
      const timer = setInterval(fetchNotifications, 60000);
      return () => clearInterval(timer);
    }
  }, [isAuthenticated, fetchNotifications]);

  // Re-fetch notifications on any data mutation (instant update)
  useEffect(() => {
    if (!isAuthenticated) return;
    const unsubscribe = subscribeToChanges(fetchNotifications);
    return unsubscribe;
  }, [isAuthenticated, subscribeToChanges, fetchNotifications]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100">
        <div className="flex flex-col items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-sky-600 text-white flex items-center justify-center animate-bounce shadow-lg shadow-sky-500/20">
            <span className="font-black text-sm">HS</span>
          </div>
          <p className="text-xs font-semibold text-slate-500 dark:text-slate-400">
            Loading household ledger...
          </p>
        </div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return <Welcome />;
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col selection:bg-sky-500 selection:text-white transition-colors duration-200">
      <Navbar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        unreadCount={notifications.length}
        onOpenNotifications={() => setIsNotificationsOpen(true)}
      />

      <main className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === 'dashboard' && <Dashboard setActiveTab={setActiveTab} />}
        {activeTab === 'bills' && <BillsRent />}
        {activeTab === 'expenses' && <Expenses />}
        {activeTab === 'pantry' && <Pantry />}
        {activeTab === 'budget' && <Budget setActiveTab={setActiveTab} />}
        {activeTab === 'ai' && <AIFeatures setActiveTab={setActiveTab} />}
        {activeTab === 'summary' && <ExpenseSummary />}
      </main>

      <NotificationsDrawer
        isOpen={isNotificationsOpen}
        onClose={() => setIsNotificationsOpen(false)}
        notifications={notifications}
        onRefresh={fetchNotifications}
        onNavigate={(tab) => {
          setActiveTab(tab);
          setIsNotificationsOpen(false);
        }}
      />
    </div>
  );
}
