const authFetch = async (url, options = {}) => {
  const headers = {
    'Cache-Control': 'no-cache, no-store, must-revalidate',
    'Pragma': 'no-cache',
    ...(options.headers || {}),
    Authorization: `Bearer ${token}`
  };
  const res = await fetch(url, { cache: 'no-store', ...options, headers });
  if (res.status === 401) {
    logout();
  }
  return res;
};

