              <div>
                <h3 className="text-base font-bold text-slate-900 dark:text-white">
                  Notifications & Reminders
                </h3>
                <p className="text-xs text-slate-500 dark:text-slate-400">
                  {notifications.length} active household alerts
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={onRefresh}
                title="Refresh Reminders"
                className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
              >
                <RefreshCw className="w-4 h-4" />
              </button>
              <button
                onClick={onClose}
                className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>

          {/* List Body */}
          <div className="flex-1 overflow-y-auto p-6 space-y-3">
            {notifications.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 text-center">
                <div className="w-14 h-14 rounded-full bg-emerald-50 dark:bg-emerald-950/60 text-emerald-500 flex items-center justify-center mb-3">
                  <CheckCircle2 className="w-7 h-7" />
                </div>
                <h4 className="text-sm font-semibold text-slate-800 dark:text-slate-200">
                  All Clear!
                </h4>
                <p className="text-xs text-slate-500 dark:text-slate-400 max-w-xs mt-1">
                  No overdue bills, upcoming due date deadlines, or low stock pantry items at this moment.
                </p>
              </div>
            ) : (
              notifications.map((notif, idx) => {
                const isOverdue = notif.urgency === 'danger' || notif.level === 'overdue';
                const isWarning = notif.urgency === 'warning' || notif.level === 'today' || notif.level === '1d';

                let borderClass = 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900';
                let iconColor = 'text-sky-500';

                if (isOverdue) {
                  borderClass = 'border-rose-200 dark:border-rose-900/50 bg-rose-50/50 dark:bg-rose-950/20';
                  iconColor = 'text-rose-500';
                } else if (isWarning) {
                  borderClass = 'border-amber-200 dark:border-amber-900/50 bg-amber-50/50 dark:bg-amber-950/20';
                  iconColor = 'text-amber-500';
                }

                return (
                  <div
                    key={idx}
                    className={`p-4 rounded-2xl border transition-all shadow-sm ${borderClass}`}
