                          {notif.message}
                        </p>

                        <div className="mt-3 flex items-center gap-3">
                          {notif.type === 'bill_reminder' && (
                            <button
                              onClick={() => {
                                onNavigate('bills');
                                onClose();
                              }}
                              className="text-[11px] font-bold underline hover:opacity-80 transition-opacity"
                            >
                              Go to Bills & Rent →
                            </button>
                          )}
                          {notif.type === 'pantry_low' && (
                            <button
                              onClick={() => {
                                onNavigate('pantry');
                                onClose();
                              }}
                              className="text-[11px] font-bold underline hover:opacity-80 transition-opacity"
                            >
                              View Suggested Shopping List →
                            </button>
                          )}
                          {(notif.type === 'budget_alert' || notif.type === 'saving_alert') && (
                            <button
                              onClick={() => {
                                onNavigate('budget');
                                onClose();
                              }}
                              className="text-[11px] font-bold underline hover:opacity-80 transition-opacity"
                            >
                              Review Monthly Budget →
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>

          {/* Footer with Real Email Dispatch Test */}
          <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/60 flex flex-col gap-2">
            <div className="flex items-center justify-between text-[11px] text-slate-500 dark:text-slate-400">
              <span>Email notifications target:</span>
              <span className="font-semibold text-slate-700 dark:text-slate-300 truncate max-w-[180px]">{user?.email}</span>
            </div>
            <button
              onClick={handleSendTestEmail}
              disabled={sendingTest}
              className="w-full flex items-center justify-center gap-2 py-2 px-3 rounded-xl bg-sky-600 hover:bg-sky-500 disabled:opacity-50 text-white font-semibold text-xs transition-colors shadow-sm"
            >
              <Mail className="w-3.5 h-3.5" />
              <span>{sendingTest ? 'Sending Test Email...' : 'Send Test Notification to Email'}</span>
            </button>
            <p className="text-[10px] text-slate-400 dark:text-slate-500 text-center">
              Delivered via configured SMTP/Gmail or previewed in Ethereal sandbox.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

